function HomelandCheckInEntryEmptyNode:Awake()
    ---@type HomelandCheckInComponent
    self.comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.HomelandCheckInComponent)
    SetButtonAction(self.Root.gameObject, function()
        local type = self.data.type
        if type == 1 then
            -- 锁定
            GameUtils.Toast(self.data.unlockDesc)
        elseif type == 2 then
            -- 消耗
            local costItems = self.data.costItems
            GameUtils.SecondConfirm(localize("确认消耗以下材料解锁档案?"), Bind(self.comp, self.comp.RequestUnlock, costItems), nil, nil, 4, costItems, true,
                nil, nil, nil, UIModule.RootCanvas.transform, 2)
        elseif type == 3 then
            -- 添加
            UIModule.OpenDialog({ id = Constants.UITypeIds.HomelandCheckInPopupSelectDialog, parameters = {type = 2}})
        end
    end)
    SetButtonAction(self.ImgIllustrate.gameObject, function()
        UIModule.OpenDialog({ id = Constants.UITypeIds.HomelandCheckInPopupOverviewDialog, parameters = {type = 1}})
    end)
    -- 绑定小红点
    GameUtils.BindRedPoint(Constants.RedPointConst.HomelandCheckInUnlockBtn, self.Root, true, nil, nil, 1)
end

function HomelandCheckInEntryEmptyNode:Start()
end

function HomelandCheckInEntryEmptyNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end
