function HomelandCheckInEntryEmptyNode:CleanProperties()
    self.data = nil
    self.comp = nil
end

function HomelandCheckInEntryEmptyNode:Refresh(data)
    self.data = data

    local type = data.type

    KTool.SetActive(self.AddGroup, type == 3)
    KTool.SetActive(self.LockGroup, type == 1)
    KTool.SetActive(self.OpenGroup, type == 2)
    -- KTool.SetActive(self.ImgNew, type == 2 or type == 3)

    CfUtils.FillText(self.TxtLock, data.unlockDesc)
end

return HomelandCheckInEntryEmptyNode